"""Config harness generated by meta-harness adapt init. Do not edit this file.

The proposer edits only the JSON between BEGIN CONFIG and END CONFIG (it is config.json);
any other change is rejected by the agent_config gate.
"""

import importlib
import json
import sys
from pathlib import Path

ENTRYPOINT = 'agent_app:run_agent'
ENTRY_PATH = 'examples/agents/support_agent'
ENTRY_BASE = 'package'

SCHEMA_JSON = r'''
{
  "type": "object",
  "required": [
    "instructions",
    "tools",
    "max_turns",
    "tool_choice"
  ],
  "frozen": [
    "tools.0.name",
    "tools.1.name"
  ],
  "properties": {
    "instructions": {
      "type": "string",
      "minLength": 1,
      "maxLength": 600
    },
    "tools": {
      "type": "array",
      "minItems": 2,
      "maxItems": 2,
      "items": {
        "type": "object",
        "required": [
          "name",
          "description"
        ],
        "properties": {
          "name": {
            "type": "string"
          },
          "description": {
            "type": "string",
            "maxLength": 200
          }
        }
      }
    },
    "max_turns": {
      "type": "integer",
      "minimum": 1,
      "maximum": 5
    },
    "tool_choice": {
      "type": "string",
      "enum": [
        "auto",
        "none"
      ]
    }
  }
}
'''

# BEGIN CONFIG
CONFIG_JSON = r'''
{
  "instructions": "You are a store support agent. Use a tool when it helps, then answer with FINAL.",
  "tools": [
    {
      "name": "lookup_order",
      "description": "internal helper"
    },
    {
      "name": "refund_order",
      "description": "Issue a refund for an order id."
    }
  ],
  "max_turns": 3,
  "tool_choice": "auto"
}
'''
# END CONFIG


def _entry_dir():
    if ENTRY_BASE == "package":
        import meta_harness
        return Path(meta_harness.__file__).resolve().parents[1] / ENTRY_PATH
    return Path(ENTRY_PATH)


def load_config():
    sibling = Path(__file__).resolve().with_name("config.json")
    if sibling.is_file():
        return json.loads(sibling.read_text(encoding="utf-8"))
    return json.loads(CONFIG_JSON)


def load_entrypoint():
    module_name, _, function = ENTRYPOINT.partition(":")
    folder = str(_entry_dir())
    if folder not in sys.path:
        sys.path.insert(0, folder)
    return getattr(importlib.import_module(module_name), function)


class Harness:
    def __init__(self):
        self.config = load_config()
        self.entry = load_entrypoint()

    def run(self, task, model, trace=None):
        result = self.entry(dict(task), json.loads(json.dumps(self.config)), model)
        if trace is not None and hasattr(trace, "event"):
            trace.event("adapter_call", {"entrypoint": ENTRYPOINT})
        if isinstance(result, dict):
            return result
        return {"output": result}
